def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The most frequent color is the background; other colors form rectangular frames.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    for color in counts:
        if color == bg:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if not (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1 + 1)) and
                all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1 + 1))):
            continue

        inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
        fill = 2 if inner_h >= 4 and inner_w >= 4 else 7
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = fill

    return out
